import csv, re, datetime
from collections import Counter, defaultdict

rows=list(csv.DictReader(open('expenses.csv')))
print("total rows", len(rows))

def parse_date(s):
    s=s.strip()
    for fmt in ("%m/%d/%Y","%d %b %Y","%Y-%m-%d","%d %B %Y"):
        try: return datetime.datetime.strptime(s,fmt).date()
        except ValueError: pass
    raise ValueError(s)

def parse_amt(s):
    s=s.strip()
    neg = s.startswith('(') and s.endswith(')')
    s=re.sub(r'[^\d.,-]','',s).replace(',','')
    return -float(s) if neg else float(s)

parsed=[]
for r in rows:
    d=parse_date(r['date'])
    a=parse_amt(r['amount'])
    parsed.append(dict(id=r['id'],date=d,cat=r['category'].strip().title(),amt=a,status=r['status'].strip().lower(),raw=r))

# exact duplicate check
seen={}
dups=[]
for p in parsed:
    key=(p['id'],p['date'],p['cat'],p['amt'],p['status'])
    if key in seen: dups.append(p)
    else: seen[key]=p
print("exact duplicate rows:", len(dups), [ (d['id'],str(d['date']),d['amt']) for d in dups])

# id conflicts
byid=defaultdict(list)
for p in parsed: byid[p['id']].append(p)
for i,v in byid.items():
    keys={(x['date'],x['cat'],x['amt'],x['status']) for x in v}
    if len(keys)>1: print("ID CONFLICT", i, v)

for p in parsed: print(p['id'],p['date'],p['cat'],p['amt'],p['status'])
EOF
