import re,csv,datetime
from decimal import Decimal
rows=list(csv.DictReader(open('expenses.csv')))
def d(s):
    s=s.strip()
    for f in ("%m/%d/%Y","%d %b %Y","%Y-%m-%d"):
        try:return datetime.datetime.strptime(s,f).date()
        except:pass
def a(s):
    return Decimal(re.sub(r'[^\d.]','',s))
seen=set();tot=Decimal(0);n=0;cats={}
for r in rows:
    k=(r['id'],r['date'],r['category'].strip().lower(),r['amount'].strip(),r['status'])
    if k in seen: continue
    seen.add(k)
    dt=d(r['date'])
    if dt.year==2026 and dt.month==10 and r['status'].strip()=='ok':
        n+=1;v=a(r['amount']);tot+=v;c=r['category'].strip().title();cats[c]=cats.get(c,Decimal(0))+v
print(n,tot,sum(cats.values()),round(tot/n,2))
print(cats)
